package no.ntnu.idata2304.smarthome.common.config;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;

/** Tests local credentials and environment precedence. Code generated by an AI. */
class LocalConfigurationTest {
  @TempDir
  Path directory;

  @Test
  void loadsNodeAndPanelTokensWithEnvironmentOverrides() throws Exception {
    Path file = directory.resolve("local.properties");
    Files.writeString(file, "SMART_HOME_NODE_12_TOKEN=local-node\n"
        + "SMART_HOME_PANEL_TOKEN=local-owner\n");

    var result = LocalConfiguration.loadCredentials(file,
        Map.of("SMART_HOME_PANEL_TOKEN", "override-owner"));

    assertEquals("local-node", result.get("SMART_HOME_NODE_12_TOKEN"));
    assertEquals("override-owner", result.get("SMART_HOME_PANEL_TOKEN"));
  }

  @Test
  void missingFileAllowsEnvironmentOnlyConfigurationWithoutDefaultTokens() throws Exception {
    var result = LocalConfiguration.loadCredentials(directory.resolve("missing.properties"),
        Map.of("SMART_HOME_NODE_13_TOKEN", "environment-node"));

    assertEquals("environment-node", result.get("SMART_HOME_NODE_13_TOKEN"));
    assertFalse(result.containsKey("SMART_HOME_NODE_12_TOKEN"));
    assertFalse(result.containsKey("SMART_HOME_PANEL_TOKEN"));
  }

  @Test
  void unreadableConfigurationIsNotSilentlyIgnored() {
    assertThrows(java.io.IOException.class,
        () -> LocalConfiguration.loadCredentials(directory, Map.of()));
  }
}
